mapper.select:
select count(1)
from cmdb_cientity_alertlevel
where id != #{id}
  and level = #{level}

select count(1)
from cmdb_cientity_alertlevel
where id != #{id}
  and name = #{name}
  and type = #{type}

select id, level, name, label, type, color
from cmdb_cientity_alertlevel
where type = #{type}

select id, level, name, label, type, color
from cmdb_cientity_alertlevel
where name = #{name}
  and type = #{type}

select id, level, name, label, type, color
from cmdb_cientity_alertlevel
where id = #{id}

select id, level, name, label, type, color
from cmdb_cientity_alertlevel
where level = #{value}

where.if:
(name like concat('%',#{keyword},'%')
or label like concat('%', #{keyword}, '%')
)
